Complete local C example; the app itself does not execute it:
```c
#include <stdio.h>
static int clamp(int n) {
    if (n < 0) return 0;
    if (n > 10) return 10;
    return n;
}
int main(void) {
    if (clamp(-1) != 0 || clamp(0) != 0 || clamp(7) != 7 ||
        clamp(10) != 10 || clamp(11) != 10) {
      puts("boundary failed"); return 1;
    }
    puts("checks passed");
    return 0;
}
```

